// =========================================================
// CONFIGURAÇÕES GERAIS — EDITE AQUI PARA TESTES
// =========================================================

// MODO_TESTE = true  -> NENHUM e-mail vai para alunos/formadores;
//                       todas as mensagens são redirecionadas para EMAIL_TESTE
//                       (o assunto mostra quem seria o destinatário real).
// MODO_TESTE = false -> envio real para os destinatários.
const MODO_TESTE = true;

// E-mail que recebe as mensagens quando MODO_TESTE = true
const EMAIL_TESTE = 'prof.flavio.spina@gmail.com';

// DIAS_A_FRENTE: quantos dias após a data ATUAL devem ser consultados.
//   1 = dia seguinte (padrão de produção)
//   2 = daqui a dois dias, e assim por diante
//   0 = o próprio dia de hoje (útil para testes)
// A regra de fim de semana continua valendo: se a data-alvo cair num sábado,
// a segunda-feira seguinte também entra como data-alvo.
const DIAS_A_FRENTE = 1;

// Pasta do Google Drive onde estão os diários (AAAA MM DD NOME DO CURSO DIÁRIO QR FORMAÇÃO)
const PASTA_DIARIOS_ID = '1-qF8Yh0oIXE8VJwypPjFkcjET1YCVmya';

// Planilha da agenda mensal (dados dos cursos e dos formadores)
const AGENDA_SHEET_ID = '11_isrdRYiew08xo7rZyBqx1YkvyfR7IRmrHui37x768';

// Data sentinela: ao encontrá-la na linha 2 da aba FREQUÊNCIA, para de percorrer a linha
const DATA_SENTINELA = '01/01/2026';

return [{
  json: {
    MODO_TESTE,
    EMAIL_TESTE,
    DIAS_A_FRENTE,
    PASTA_DIARIOS_ID,
    AGENDA_SHEET_ID,
    DATA_SENTINELA
  }
}];

const cfg = $('Config - Variáveis').first().json;
const tz = 'America/Sao_Paulo';

function pad(v) {
  return String(v).padStart(2, '0');
}

const dias = Number(cfg.DIAS_A_FRENTE);
if (!Number.isFinite(dias) || dias < 0) {
  throw new Error('DIAS_A_FRENTE inválido: use um número inteiro >= 0 (1 = dia seguinte).');
}

const now = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
const target = new Date(now);
target.setDate(target.getDate() + Math.trunc(dias));

function buildDateMeta(date, label) {
  const yyyy = date.getFullYear();
  const mm = pad(date.getMonth() + 1);
  const dd = pad(date.getDate());
  return {
    label,
    yyyy,
    mm,
    dd,
    target_day: dd,
    target_ymd: `${yyyy}-${mm}-${dd}`,
    target_ddmmyyyy: `${dd}/${mm}/${yyyy}`,
    weekday: date.toLocaleDateString('pt-BR', { timeZone: tz, weekday: 'long' })
  };
}

const targets = [buildDateMeta(target, 'data_alvo')];

// Regra de fim de semana: se a data-alvo for sábado, inclui também a segunda-feira.
if (target.getDay() === 6) {
  const monday = new Date(target);
  monday.setDate(monday.getDate() + 2);
  targets.push(buildDateMeta(monday, 'segunda_antecipada'));
}

const target_days = [...new Set(targets.map(t => t.target_day))];
const target_ymds = [...new Set(targets.map(t => t.target_ymd))];
const target_ddmmyyyys = [...new Set(targets.map(t => t.target_ddmmyyyy))];
const month_tabs = [...new Set(targets.map(t => {
  const m = new Date(`${t.target_ymd}T12:00:00`);
  const monthName = m.toLocaleDateString('pt-BR', { timeZone: tz, month: 'long' });
  return monthName.charAt(0).toUpperCase() + monthName.slice(1);
}))];

return [{
  json: {
    modo_teste: cfg.MODO_TESTE,
    dias_a_frente: Math.trunc(dias),
    hoje: `${pad(now.getDate())}/${pad(now.getMonth() + 1)}/${now.getFullYear()}`,
    target_day: target_days[0],
    target_ymd: target_ymds[0],
    target_ddmmyyyy: target_ddmmyyyys[0],
    month_tab: month_tabs[0],
    target_days,
    target_ymds,
    target_ddmmyyyys,
    month_tabs,
    targets,
    includes_monday_advance: targets.some(t => t.label === 'segunda_antecipada')
  }
}];

const prep = $('Preparar Data Alvo').first().json;

function pad(v) {
  return String(v).padStart(2, '0');
}

function normalizeDateValue(raw) {
  if (raw === null || raw === undefined || raw === '') return null;

  if (typeof raw === 'number') {
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const date = new Date(excelEpoch.getTime() + raw * 86400000);
    return {
      ymd: `${date.getUTCFullYear()}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())}`,
      day: pad(date.getUTCDate())
    };
  }

  const str = String(raw).trim();
  if (!str) return null;

  const br = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (br) {
    const [, d, m, y] = br;
    return { ymd: `${y}-${pad(m)}-${pad(d)}`, day: pad(d) };
  }

  const iso = str.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) {
    const [, y, m, d] = iso;
    return { ymd: `${y}-${m}-${d}`, day: d };
  }

  const onlyDay = str.match(/^\d{1,2}$/);
  if (onlyDay) {
    return { ymd: null, day: pad(str) };
  }

  return null;
}

const targetDays = new Set((prep.target_days || []).map(v => String(v).padStart(2, '0')));
const targetYmds = new Set(prep.target_ymds || []);

const seen = new Set();
const agenda = [];

for (const item of items) {
  const row = item.json;
  const parsed = normalizeDateValue(row['DATA'] ?? row['Data'] ?? row['data']);
  if (!parsed) continue;

  const match = (parsed.ymd && targetYmds.has(parsed.ymd)) || targetDays.has(parsed.day);
  if (!match) continue;

  const key = [row['DATA'] ?? '', row['TÍTULO'] ?? '', row['INÍCIO'] ?? row['INICIO'] ?? ''].join('|');
  if (seen.has(key)) continue;
  seen.add(key);

  agenda.push({ ...row, _data_ymd: parsed.ymd || '', _data_dia: parsed.day });
}

// Empacota tudo em UM item para o fluxo continuar mesmo sem cursos na agenda.
return [{ json: { _agenda: agenda, _agendaCount: agenda.length } }];

function normalize(s = '') {
  return String(s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\.(xlsx|xls|csv)$/i, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const seen = new Set();
const out = [];

for (const item of items) {
  const id = String(item.json.id || '').trim();
  const name = String(item.json.name || '').trim();
  if (!id || !name || seen.has(id)) continue;
  seen.add(id);

  // Apenas arquivos "... DIÁRIO QR FORMAÇÃO"
  const norm = normalize(name);
  if (!norm.includes('diario qr formacao')) continue;

  // Nome do curso = nome do arquivo sem o prefixo "AAAA MM DD" e sem o sufixo "DIÁRIO QR FORMAÇÃO"
  const curso_nome = name
    .replace(/^\s*\d{4}[\s._-]+\d{1,2}[\s._-]+\d{1,2}[\s._-]*/, '')
    .replace(/[-–—]?\s*di[aá]rio\s+qr\s+forma[cç][aã]o.*$/i, '')
    .replace(/\.(xlsx|xls|csv)$/i, '')
    .trim() || name;

  out.push({
    json: {
      spreadsheetId: id,
      spreadsheetName: name,
      curso_nome,
      course_key: normalize(curso_nome)
    }
  });
}

out.sort((a, b) => a.json.spreadsheetName.localeCompare(b.json.spreadsheetName, 'pt-BR'));

return out;

const prep = $('Preparar Data Alvo').first().json;
const cfg = $('Config - Variáveis').first().json;

// Os diários originais, na MESMA ordem em que entraram no nó HTTP
// (o nó HTTP devolve exatamente um item de resposta por item de entrada).
const diarios = $('Code - Preparar Diários').all().map(i => i.json);

function pad(v) {
  return String(v).padStart(2, '0');
}

function toDate(raw) {
  if (raw === null || raw === undefined || raw === '') return null;

  if (typeof raw === 'number') {
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const d = new Date(excelEpoch.getTime() + raw * 86400000);
    return {
      ddmmyyyy: `${pad(d.getUTCDate())}/${pad(d.getUTCMonth() + 1)}/${d.getUTCFullYear()}`,
      ddmm: `${pad(d.getUTCDate())}/${pad(d.getUTCMonth() + 1)}`
    };
  }

  const str = String(raw).trim();
  if (!str) return null;

  let m = str.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return { ddmmyyyy: `${pad(m[1])}/${pad(m[2])}/${m[3]}`, ddmm: `${pad(m[1])}/${pad(m[2])}` };

  m = str.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m) return { ddmmyyyy: `${m[3]}/${m[2]}/${m[1]}`, ddmm: `${m[3]}/${m[2]}` };

  m = str.match(/^(\d{1,2})\/(\d{1,2})$/);
  if (m) return { ddmmyyyy: '', ddmm: `${pad(m[1])}/${pad(m[2])}` };

  return null;
}

const sentinela = toDate(cfg.DATA_SENTINELA) || { ddmmyyyy: '01/01/2026', ddmm: '01/01' };
const targetsFull = new Set(prep.target_ddmmyyyys || []);
const targetsDDMM = new Set((prep.target_ddmmyyyys || []).map(v => v.slice(0, 5)));

const out = [];

items.forEach((item, idx) => {
  const resp = item.json || {};
  const diario = diarios[idx] || {};

  const row = Array.isArray(resp.values) && Array.isArray(resp.values[0]) ? resp.values[0] : [];

  let erroLeitura = '';
  if (resp.error) {
    erroLeitura = typeof resp.error === 'string' ? resp.error : (resp.error.message || 'Erro ao ler a aba FREQUÊNCIA');
  }

  // Percorre a linha 2 a partir de L2; para na sentinela (01/01/2026).
  let matched = '';
  for (const cell of row) {
    const d = toDate(cell);
    if (!d) continue;

    const isSentinela =
      (d.ddmmyyyy && sentinela.ddmmyyyy && d.ddmmyyyy === sentinela.ddmmyyyy) ||
      (!d.ddmmyyyy && d.ddmm === sentinela.ddmm);
    if (isSentinela) break;

    const isAlvo =
      (d.ddmmyyyy && targetsFull.has(d.ddmmyyyy)) ||
      (!d.ddmmyyyy && targetsDDMM.has(d.ddmm));
    if (isAlvo) {
      matched = d.ddmmyyyy || [...targetsFull].find(t => t.startsWith(d.ddmm)) || d.ddmm;
      break;
    }
  }

  if (matched) {
    out.push({
      json: {
        spreadsheetId: diario.spreadsheetId,
        spreadsheetName: diario.spreadsheetName,
        curso_nome: diario.curso_nome,
        course_key: diario.course_key,
        TEM_CURSO: true,
        DATA_MATCH: matched,
        ERRO_LEITURA: erroLeitura
      }
    });
  }
});

if (!out.length) {
  return [{
    json: {
      TEM_CURSO: false,
      _motivo: 'Nenhum diário com aula na(s) data(s)-alvo: ' + (prep.target_ddmmyyyys || []).join(', ')
    }
  }];
}

return out;

// Monta UMA fila ordenada de envios:
//   alunos do curso 1 -> formadores do curso 1 -> alunos do curso 2 -> ...
// Assim o envio usa um ÚNICO loop, evitando o bug conhecido do n8n com
// loops aninhados de Split In Batches (github.com/n8n-io/n8n/issues/23670).

const agenda = ($('Code - Agenda Dia Seguinte').first().json._agenda) || [];

// Cursos com aula na data-alvo, na MESMA ordem em que entraram no nó HTTP.
const cursos = $('Code - Verificar Datas').all().map(i => i.json);

function normalize(s = '') {
  return String(s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\.(xlsx|xls|csv)$/i, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function scoreMatch(fileKey, agendaKey) {
  if (!fileKey || !agendaKey) return 0;
  if (fileKey === agendaKey) return 1000;
  if (fileKey.includes(agendaKey) || agendaKey.includes(fileKey)) return 800;

  const fileTokens = new Set(fileKey.split(' ').filter(Boolean));
  const agendaTokens = new Set(agendaKey.split(' ').filter(Boolean));

  let common = 0;
  for (const t of fileTokens) {
    if (agendaTokens.has(t)) common++;
  }
  if (!common) return 0;
  return common * 10 - Math.abs(fileTokens.size - agendaTokens.size);
}

function formadoresDisplay(raw) {
  return String(raw || '')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map(l => l
      .replace(/^[-–•\s]+/, '')
      .replace(/\s*[-–]\s*[^\s@]+@[^\s@]+\.[^\s@]+\s*$/i, '')
      .replace(/<[^>]*>/g, '')
      .trim())
    .filter(Boolean)
    .filter(l => !/^(formadores|professores)( externos)?:?$/i.test(l))
    .join(', ');
}

function normalizeRawText(text = '') {
  return String(text || '')
    .replace(/\\r\\n/g, '\n')
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\n')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

function splitLines(text = '') {
  return normalizeRawText(text)
    .split('\n')
    .map(v => v.trim())
    .filter(Boolean);
}

function cleanLine(value = '') {
  return String(value || '')
    .replace(/^[-–•\s]+/, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isHeaderLine(s) {
  const t = String(s || '').trim().toUpperCase();
  return [
    'FORMADORES:',
    'FORMADORES',
    'FORMADORES EXTERNOS:',
    'FORMADORES EXTERNOS',
    'PROFESSORES:',
    'PROFESSORES',
    'PROFESSORES EXTERNOS:',
    'PROFESSORES EXTERNOS'
  ].includes(t);
}

function parsePerson(rawLine) {
  const value = cleanLine(rawLine);
  if (!value || isHeaderLine(value)) return null;

  let m = value.match(/^(.*?)\s*-\s*([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})$/i);
  if (m) {
    return { nome: cleanLine(m[1]), email: m[2].trim().toLowerCase() };
  }

  m = value.match(/^(.*?)<\s*([^>]+@[^>]+)\s*>$/);
  if (m) {
    return { nome: cleanLine(m[1]) || m[2].trim(), email: m[2].trim().toLowerCase() };
  }

  m = value.match(/^([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})$/i);
  if (m) {
    return { nome: m[1].trim(), email: m[1].trim().toLowerCase() };
  }

  return null;
}

// ----- frases dinâmicas conforme a distância entre hoje e a data do curso -----
const hojeStr = $('Preparar Data Alvo').first().json.hoje; // DD/MM/AAAA

function parseBR(s) {
  const m = String(s || '').match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  return m ? new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]), 12, 0, 0) : null;
}

function capitalize(s) {
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
}

function frasesDoDia(dataBR) {
  if (!dataBR) {
    return { DIA_SEMANA: '', FRASE_ABERTURA: 'Em breve', REF_DIA: 'do curso' };
  }
  const alvo = parseBR(dataBR);
  const hoje = parseBR(hojeStr);
  const weekday = alvo ? capitalize(alvo.toLocaleDateString('pt-BR', { weekday: 'long' })) : '';
  const diff = (alvo && hoje) ? Math.round((alvo - hoje) / 86400000) : null;
  const masculino = /sábado|domingo/i.test(weekday);

  // FRASE_ABERTURA completa a frase: "... teremos um compromisso importante no CECAPE!"
  // REF_DIA completa a frase: "... a mensagem sobre o compromisso ..."
  if (diff === 0) {
    return { DIA_SEMANA: weekday, FRASE_ABERTURA: `Hoje, ${weekday},`, REF_DIA: `de hoje (${weekday})` };
  }
  if (diff === 1) {
    return { DIA_SEMANA: weekday, FRASE_ABERTURA: `Amanhã, ${weekday},`, REF_DIA: `de amanhã (${weekday})` };
  }
  if (diff !== null && diff > 1) {
    return {
      DIA_SEMANA: weekday,
      FRASE_ABERTURA: masculino
        ? `No próximo ${weekday}, dia ${dataBR},`
        : `Na próxima ${weekday}, dia ${dataBR},`,
      REF_DIA: masculino
        ? `do próximo ${weekday} (${dataBR})`
        : `da próxima ${weekday} (${dataBR})`
    };
  }
  return { DIA_SEMANA: weekday, FRASE_ABERTURA: `No dia ${dataBR},`, REF_DIA: `do dia ${dataBR}` };
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const fila = [];

items.forEach((item, idx) => {
  const resp = item.json || {};
  const info = cursos[idx] || {};
  const dm = String(info.DATA_MATCH || '');

  // ----- localizar o curso na agenda mensal (sala, horário, formadores) -----
  let curso = null;
  let bestScore = 0;

  for (const a of agenda) {
    const aKey = normalize(a['TÍTULO'] || a['TITULO'] || '');
    let score = scoreMatch(info.course_key, aKey);
    if (dm && a._data_ymd && dm === a._data_ymd.split('-').reverse().join('/')) score += 50;
    else if (dm && a._data_dia && dm.slice(0, 2) === a._data_dia) score += 20;
    if (score > bestScore) {
      bestScore = score;
      curso = a;
    }
  }

  const encontrado = !!curso && bestScore >= 10;
  const formadoresRaw = encontrado ? String(curso['FORMADORES'] ?? curso['PROFESSORES'] ?? '') : '';

  const cursoInfo = {
    spreadsheetId: info.spreadsheetId,
    spreadsheetName: info.spreadsheetName,
    curso_nome: info.curso_nome,
    course_key: info.course_key,
    DATA: dm || (encontrado ? String(curso['DATA'] ?? '') : ''),
    'TÍTULO': encontrado && curso['TÍTULO'] ? curso['TÍTULO'] : info.curso_nome,
    'ESPAÇO': encontrado ? (curso['ESPAÇO'] ?? curso['ESPACO'] ?? '') : '',
    INICIO: encontrado ? (curso['INÍCIO'] ?? curso['INICIO'] ?? '') : '',
    TERMINO: encontrado ? (curso['TÉRMINO'] ?? curso['TERMINO'] ?? '') : '',
    ETAPAS: encontrado ? (curso['ETAPAS'] ?? '') : '',
    FORMATO: encontrado ? (curso['FORMATO'] ?? '') : '',
    'GOOGLE SALA DE AULA': encontrado ? (curso['GOOGLE SALA DE AULA'] ?? '') : '',
    FORMADORES: formadoresDisplay(formadoresRaw),
    CURSO_ENCONTRADO_NA_AGENDA: encontrado,
    SCORE_AGENDA: bestScore
  };

  Object.assign(cursoInfo, frasesDoDia(cursoInfo.DATA));

  // ----- alunos: coluna C = nome, coluna D = e-mail (a partir da linha 3) -----
  const rows = Array.isArray(resp.values) ? resp.values : [];
  const seenAlunos = new Set();

  for (const r of rows) {
    const nome = String((r && r[0]) || '').trim();
    const email = String((r && r[1]) || '').trim().toLowerCase();
    if (!email || !emailRegex.test(email)) continue;
    if (seenAlunos.has(email)) continue;
    seenAlunos.add(email);

    fila.push({
      json: {
        ...cursoInfo,
        TIPO_ENVIO: 'ALUNO',
        NOME: nome || email,
        EMAIL_ALUNO: email
      }
    });
  }

  // ----- formadores do MESMO curso, logo após os alunos -----
  const seenProf = new Set();

  for (const linha of splitLines(formadoresRaw)) {
    const p = parsePerson(linha);
    if (!p || !p.email) continue;
    if (seenProf.has(p.email)) continue;
    seenProf.add(p.email);

    fila.push({
      json: {
        ...cursoInfo,
        TIPO_ENVIO: 'FORMADOR',
        PROFESSOR_NOME: p.nome,
        PROFESSOR_EMAIL: p.email,
        HORARIO_INICIO: cursoInfo.INICIO || '',
        HORARIO_FIM: cursoInfo.TERMINO || '',
        TITULO_CURSO: cursoInfo['TÍTULO'] || info.curso_nome
      }
    });
  }
});

if (!fila.length) {
  return [{
    json: {
      TIPO_ENVIO: 'NENHUM',
      _motivo: 'Cursos com aula na data-alvo foram encontrados, mas sem alunos/formadores com e-mail válido.'
    }
  }];
}

return fila.map((f, i) => ({ json: { ...f.json, ORDEM: i + 1, TOTAL_FILA: fila.length } }));

